14.query:
// Log indicators (rebuilt from the Dynatrace PHP2Shell blog). These suggest attempts; they do not confirm exploitation.
fetch logs
| filter matchesValue(content, "*Allowed memory size of*")
      or matchesValue(content, "*Maximum execution time*")
      or matchesValue(content, "*exit signal Segmentation fault*")
      or matchesValue(content, "*exited on signal 11*")
      or matchesValue(content, "*PHP Fatal error*")
| fieldsAdd indicator = if(matchesValue(content, "*Allowed memory size of*"), "memory exhausted",
    else: if(matchesValue(content, "*Maximum execution time*"), "execution timeout",
    else: if(matchesValue(content, "*Segmentation fault*") or matchesValue(content, "*signal 11*"), "segfault",
    else: "PHP fatal error")))
| summarize events = count(), first = min(timestamp), last = max(timestamp), by: {host.name, indicator}
| sort events desc
| limit 50
